def render(lang, data, slug):
    _, en_title, en_desc, zh_title, zh_desc, keyword, en_steps, zh_steps = data
    title, desc, steps = (en_title, en_desc, en_steps) if lang == 'en' else (zh_title, zh_desc, zh_steps)
    root = ROOT / slug if lang == 'en' else ROOT / 'zh' / slug
    root.mkdir(parents=True, exist_ok=True)
    prefix = '../assets/' if lang == 'en' else '../../assets/'
    home = '../index.html' if lang == 'en' else '../../zh.html'
    canonical = BASE + ('' if lang == 'en' else 'zh/') + slug + '/'
    if lang == 'en':
        heading = 'Step-by-step workflow'
        audience = f"This guide is useful for creators, editors and marketing teams searching for {keyword}. It focuses on the job behind the search: turning a long recording into short videos that make sense on their own and give viewers a reason to watch more."
        context = f"The best {keyword} workflow starts with a clear audience question. A podcast clip should answer or challenge an idea; a stream highlight should show the moment and reaction; a YouTube to Shorts edit should deliver one useful takeaway. Start by deciding what the viewer should understand or feel before choosing a timestamp."
        mistakes = ["Choosing a moment that needs ten minutes of context", "Opening with a greeting instead of the payoff", "Adding captions without checking mobile readability", "Publishing every clip at once without a repeatable schedule"]
        faq = [(f"How does {keyword} help with long-form video?", f"It shortlists meaningful moments, then helps you prepare captions, framing and publishing copy so you spend more time editing the story and less time scrubbing through the recording."), ("How long should each clip be?", "Use the shortest edit that preserves the idea. A complete answer is more useful than an arbitrary duration; remove pauses and repeated setup while keeping the context needed to understand the point."), ("What should I measure after publishing?", "Compare retention, rewatches, comments and qualified clicks. Use those signals to improve the next hook instead of treating a single view count as a promise of performance."), ("Should every clip use the same hook?", "Keep a recognizable format, but test different openings. A question, a surprising result and a strong quote can all introduce the same source moment to different audiences."), ("How do I avoid making clips feel repetitive?", "Assign each clip one distinct promise. Change the topic, emotional beat or audience question, and use a publishing schedule that gives each idea room to be discovered.")]
        faq_heading = 'Frequently asked questions'
        mistakes_heading = 'Common mistakes to avoid'
        planning = f"Before opening the editor, write down three things: the intended viewer, the question this clip answers, and the action you want after viewing. This short brief prevents a common problem with {keyword}: selecting moments that sound interesting inside the recording but have no clear promise for someone scrolling a feed. It also gives you a useful way to compare candidate clips."
        editing = f"Use the first pass to remove dead air, repeated setup and references that only make sense to people who watched the full source. On the second pass, check the opening, captions and framing on a phone-sized screen. A good {keyword} edit should communicate its topic before the viewer has to guess, keep the speaker or subject visible, and reach a useful answer quickly."
        distribution = "Prepare a small batch instead of one isolated export. Create a primary vertical version, then adapt the title, description and opening line for each channel. Schedule clips around the source topic, event or episode so the content has a reason to appear now. Keep a simple spreadsheet with the source timestamp, hook used, platform, publish date and result."
        closing = f"ShortMind brings highlight detection, captions, AI reframing and publishing copy into one {keyword} workflow. Start with one long recording, review the suggested moments, and build a useful batch rather than chasing a single lucky clip."
        extra_headings = ('Plan the clip before you edit', 'Editing checklist for a stronger result', 'Turn one source into a publishing series')
        extra_paragraphs = (planning, editing, distribution)
    else:
        heading = '分步工作流'
        audience = f"这篇内容适合正在寻找“{keyword}”解决方案的创作者、剪辑人员和营销团队。重点不是堆叠功能，而是把长录制变成脱离原视频也能看懂、并且能引导观众继续了解的短视频。"
        context = f"好的“{keyword}”流程，应该先明确受众问题，再选择时间点。播客切片要完整表达观点，直播高光要同时呈现关键动作和反应，YouTube 转 Shorts 要让观众快速获得一个有用结论。先确定观众需要理解或感受到什么，再开始找片段。"
        mistakes = ["选择必须依赖十分钟上下文才能看懂的片段", "开头使用问候和铺垫，没有尽早呈现重点", "添加字幕后没有检查手机屏幕上的可读性", "一次发布所有片段，没有建立持续排期"]
        faq = [(f"{keyword} 能解决什么问题？", "它可以从长视频中筛选有意义的片段，并协助完成字幕、画面构图和发布文案，减少反复拖动回放寻找素材的时间。"), ("短视频应该多长？", "不要为了固定时长牺牲完整表达。保留理解观点所需的上下文，删除停顿和重复铺垫，让结论尽早出现。"), ("发布后应该看哪些数据？", "关注完播、重复观看、评论和有效点击，根据这些反馈调整下一条短片的开场，而不是只看一次播放量。"), ("每条短片都要使用相同的开场吗？", "可以保持统一的栏目风格，但要测试不同开场。问题、结果和金句都可以介绍同一个片段，适合不同受众。"), ("如何避免批量短片看起来重复？", "让每条短片只承诺一个明确主题，改变话题、情绪节点或受众问题，并通过排期给每个观点足够的传播空间。")]
        faq_heading = '常见问题'
        mistakes_heading = '常见错误与改进方法'
        planning = f"打开剪辑工具前，先写下三个信息：目标观众是谁、这条短片回答什么问题、观众看完后应该采取什么行动。这个小 brief 可以避免“{keyword}”中最常见的问题：片段在完整录制里很有趣，但放到信息流里没有明确承诺，也无法让陌生观众快速理解。"
        editing = f"第一遍剪辑先删除停顿、重复铺垫以及只有看过完整视频才能理解的上下文。第二遍用手机尺寸检查开头、字幕和画面构图。好的“{keyword}”短片应该在观众猜测之前说明主题，让人物或主体始终清晰可见，并尽快给出有用结论。"
        distribution = "不要只导出一条孤立短片，建议围绕同一条长视频制作一个小批次。先生成主版本，再针对不同平台调整标题、描述和开场。根据节目、活动或热点安排发布时间，并记录原视频时间点、使用的钩子、平台、发布日期和结果。"
        closing = f"ShortMind 将高光识别、字幕、AI 智能重构画面和发布文案连接成一套“{keyword}”工作流。可以先从一条长视频开始，审核推荐片段，再批量制作服务于明确受众需求的短视频，而不是只等待一条片段偶然爆发。"
        extra_headings = ('剪辑前先明确短片任务', '提升成片质量的检查清单', '把一条长视频变成连续内容')
        extra_paragraphs = (planning, editing, distribution)
    steps_html = ''.join(f'<li><strong>{escape(step)}</strong><p>{escape(context if i == 0 else audience if i == 1 else "Review the clip on a phone-sized screen, remove repeated setup, and keep the payoff close to the opening." if lang == "en" else "用手机尺寸预览片段，删除重复铺垫，让重点尽量靠近开头。")}</p></li>' for i, step in enumerate(steps))
    mistakes_html = ''.join(f'<li>{escape(m)}</li>' for m in mistakes)
    faq_html = ''.join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q, a in faq)
    schema = json.dumps({"@context": "https://schema.org", "@type": "Article", "headline": title, "description": desc, "mainEntityOfPage": canonical}, ensure_ascii=False)
    footer = f'<footer class="footer"><div class="container"><div class="footer-inner"><a class="brand" href="{home}"><img src="{prefix}brand-mark.webp" width="32" height="32" alt=""><span>ShortMind</span></a><nav class="footer-links"><a href="{CTA}">shortmind.ai ↗</a><a href="https://github.com/ShortMindAI/shortmindai.github.io">GitHub ↗</a><a href="{home}">{"English README" if lang == "en" else "中文 README"}</a></nav></div><p class="copyright">© 2026 ShortMind · {"AI video clipping & content repurposing" if lang == "en" else "AI 视频切片与内容再利用"}</p></div></footer>'
    extra_html = ''.join(f'<h2>{escape(h)}</h2><p>{escape(p)}</p>' for h, p in zip(extra_headings, extra_paragraphs))
    if lang == 'en':
        nav = f'<nav class="nav-links"><a href="{home}#features">Features</a><a href="{home}#workflow">How it works</a><a href="{home}#use-cases">Use cases</a><a href="../resources/">Resources</a><a href="{home}#faq">FAQ</a><a href="https://github.com/ShortMindAI/shortmindai.github.io">GitHub ↗</a></nav>'
        actions = f'<nav class="nav-actions"><a class="language" href="./" lang="en" aria-current="page">EN</a><a class="language" href="../zh/{slug}/" lang="zh-CN">中文</a><a class="button primary small" href="{CTA}">Visit website ↗</a></nav>'
    else:
        nav = f'<nav class="nav-links"><a href="{home}#features">核心功能</a><a href="{home}#workflow">使用流程</a><a href="{home}#use-cases">应用场景</a><a href="../resources/">教程与案例</a><a href="{home}#faq">常见问题</a><a href="https://github.com/ShortMindAI/shortmindai.github.io">GitHub ↗</a></nav>'
        actions = f'<nav class="nav-actions"><a class="language" href="../../{slug}/" lang="en">EN</a><a class="language" href="./" lang="zh-CN" aria-current="page">中文</a><a class="button primary small" href="{CTA}">访问官网 ↗</a></nav>'
    resource_home = '../resources/'
    breadcrumb_label = 'Resources' if lang == 'en' else '教程与案例'
    html = f'''<!doctype html><html lang="{'en' if lang == 'en' else 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | ShortMind</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en" href="{BASE}{slug}/"><link rel="alternate" hreflang="zh-CN" href="{BASE}zh/{slug}/"><link rel="alternate" hreflang="x-default" href="{BASE}{slug}/"><link rel="stylesheet" href="{prefix}site.css"><meta property="og:title" content="{escape(title)} | ShortMind"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="article"><meta property="og:url" content="{canonical}"><script type="application/ld+json">{schema}</script></head><body class="seo-page"><header class="header"><div class="container nav"><a class="brand" href="{home}"><img src="{prefix}brand-mark.webp" width="32" height="32" alt=""><span>ShortMind</span></a>{nav}{actions}</div></header><main class="container seo-main"><p class="breadcrumb"><a href="{resource_home}">{breadcrumb_label}</a> / {escape(keyword)}</p><article class="article"><p class="eyebrow">{escape(keyword)}</p><h1>{escape(title)}</h1><p class="seo-lead">{escape(desc)}</p><p>{escape(audience)}</p><h2>{'What makes this workflow effective' if lang == 'en' else '为什么要按场景设计工作流'}</h2><p>{escape(context)}</p>{extra_html}<h2>{heading}</h2><ol class="steps-list">{steps_html}</ol><h2>{mistakes_heading}</h2><ul class="intent-list">{mistakes_html}</ul><h2>{faq_heading}</h2><div class="faq">{faq_html}</div><h2>{'Build your next batch of clips' if lang == 'en' else '开始制作下一批短视频'}</h2><p>{escape(closing)}</p><p><a class="button primary" href="{CTA}">{'Try ShortMind AI' if lang == 'en' else '体验 ShortMind AI'} →</a></p></article></main>{footer}</body></html>'''
    (root / 'index.html').write_text(html, encoding='utf-8')

def main():
    for data in ARTICLES:
        slug = data[0]
        render('en', data, slug)
        render('zh', data, slug)
    cards_en = ''.join(f'<article class="resource-card"><h2><a href="../{d[0]}/">{escape(d[1])}</a></h2><p>{escape(d[2])}</p></article>' for d in ARTICLES)
    cards_zh = ''.join(f'<article class="resource-card"><h2><a href="../{d[0]}/">{escape(d[3])}</a></h2><p>{escape(d[4])}</p></article>' for d in ARTICLES)
    for lang, cards, folder, title, desc, home, prefix in [('en', cards_en, ROOT/'resources', 'Short-form video tutorials and case studies', 'Practical guides for AI clip maker, long video to shorts, podcast clips, YouTube to Shorts, stream highlights and stream clips.', '../index.html', '../assets/'), ('zh', cards_zh, ROOT/'zh/resources', '短视频教程与场景案例', '围绕 AI 视频切片、长视频转短视频、播客切片、YouTube 转 Shorts、直播高光和 Stream Clips 的实用内容。', '../../zh.html', '../../assets/')]:
        folder.mkdir(parents=True, exist_ok=True)
        canonical = BASE + ('resources/' if lang == 'en' else 'zh/resources/')
        if lang == 'en':
            nav = f'<nav class="nav-links"><a href="{home}#features">Features</a><a href="{home}#workflow">How it works</a><a href="{home}#use-cases">Use cases</a><a href="./">Resources</a><a href="{home}#faq">FAQ</a><a href="https://github.com/ShortMindAI/shortmindai.github.io">GitHub ↗</a></nav>'
            language_links = '<a class="language" href="./" lang="en" aria-current="page">EN</a><a class="language" href="../zh/resources/" lang="zh-CN">中文</a>'
        else:
            nav = f'<nav class="nav-links"><a href="{home}#features">核心功能</a><a href="{home}#workflow">使用流程</a><a href="{home}#use-cases">应用场景</a><a href="./">教程与案例</a><a href="{home}#faq">常见问题</a><a href="https://github.com/ShortMindAI/shortmindai.github.io">GitHub ↗</a></nav>'
            language_links = '<a class="language" href="../../resources/" lang="en">EN</a><a class="language" href="./" lang="zh-CN" aria-current="page">中文</a>'
        footer = f'<footer class="footer"><div class="container"><div class="footer-inner"><a class="brand" href="{home}"><img src="{prefix}brand-mark.webp" width="32" height="32" alt=""><span>ShortMind</span></a><nav class="footer-links"><a href="{CTA}">shortmind.ai ↗</a><a href="https://github.com/ShortMindAI/shortmindai.github.io">GitHub ↗</a><a href="{home}">{"English README" if lang == "en" else "中文 README"}</a></nav></div><p class="copyright">© 2026 ShortMind · {"AI video clipping & content repurposing" if lang == "en" else "AI 视频切片与内容再利用"}</p></div></footer>'
        html = f'''<!doctype html><html lang="{'en' if lang == 'en' else 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | ShortMind</title><meta name="description" content="{desc}"><link rel="canonical" href="{canonical}"><link rel="stylesheet" href="{prefix}site.css"></head><body class="seo-page"><header class="header"><div class="container nav"><a class="brand" href="{home}"><img src="{prefix}brand-mark.webp" width="32" height="32" alt=""><span>ShortMind</span></a>{nav}<nav class="nav-actions">{language_links}<a class="button primary small" href="{CTA}">{'Visit website ↗' if lang == 'en' else '访问官网 ↗'}</a></nav></div></header><main class="container seo-main"><p class="breadcrumb"><a href="{home}">ShortMind</a> / {title}</p><section class="seo-hero"><p class="eyebrow">ShortMind Resources</p><h1>{title}</h1><p class="seo-lead">{desc}</p></section><section class="resource-grid">{cards}</section></main>{footer}</body></html>'''
        (folder/'index.html').write_text(html, encoding='utf-8')
    urls = [''] + [f'{d[0]}/' for d in ARTICLES] + [f'zh/{d[0]}/' for d in ARTICLES] + ['resources/', 'zh/resources/']
    xml = ['<?xml version="1.0" encoding="UTF-8"?>', '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'] + [f'  <url><loc>{BASE}{u}</loc></url>' for u in urls] + ['</urlset>']
    (ROOT/'sitemap.xml').write_text('\n'.join(xml)+'\n', encoding='utf-8')

if __name__ == '__main__':
    main()
